const shop = 'vdzvc0-nd';

const createdMin = DateTime.now().setZone('Europe/Berlin').minus({ days: 30 }).startOf('day').plus({ hours: 6 }).toISO();
const createdMax = DateTime.now().setZone('Europe/Berlin').startOf('day').plus({ hours: 6 }).toISO();

const initUrlB = `https://${shop}.myshopify.com/admin/api/2024-10/orders.json`
  + `?status=any`
  + `&limit=250`
  + `&order=created_at+asc`
  + `&fields=id,name,tags`
  + `&created_at_min=${encodeURIComponent(createdMin)}`
  + `&created_at_max=${encodeURIComponent(createdMax)}`;

// Globales Array leeren
const staticData = $getWorkflowStaticData('global');
staticData.collectedOrdersB = [];

return [{
  json: {
    nextUrl: initUrlB,
    hasNext: true
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];
const respHeaders = response.headers || {};
const linkHeader = respHeaders.link || respHeaders.Link || '';

// Filter Abo-Bestellungen
const filtered = orders.filter(order =>
  (order.tags || '')
    .split(',')
    .map(t => t.trim())
    .includes('appstle_subscription_recurring_order')
);

// In globales Array pushen
const staticData = $getWorkflowStaticData('global');
staticData.collectedOrdersB = (staticData.collectedOrdersB || []).concat(filtered);

// Next URL extrahieren
const nextMatch = linkHeader
  .split(',')
  .find(s => s.includes('rel="next"'));
const nextUrl = nextMatch ? nextMatch.match(/<(.+?)>/)?.[1] : null;

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    collectedCount: staticData.collectedOrdersB.length
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.collectedOrdersB || [];

return collected.map(order => ({ json: order }));

const items = $input.all();

const seen = new Set();
const unique = [];

for (const item of items) {
  const id = item.json.id;
  if (!seen.has(id)) {
    seen.add(id);
    unique.push(item);
  }
}

return unique;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

