SELECT cExterneAuftragsnummer, cAuftragsNr 
FROM Verkauf.tAuftrag
WHERE cAuftragsNr = '{{ $json.name }}';

parameters.jsCode:
const items = $input.all();

// Pakete = alle Items, die eine cAuftragsNr mitbringen
const pakete = items.filter(item => item.json && item.json.cAuftragsNr);

if (pakete.length === 0) {
  return [{
    json: {
      mailText: `<p>Es wurden keine externen Auftragsnummern angepasst.</p>
<p>Mit freundlichen Grüßen<br>Jesse's n8n-Workflow</p>`,
    },
  }];
}

const listenEintraege = pakete
  .map(item => `  <li>${item.json.cAuftragsNr}</li>`)
  .join('\n');

const mailText = `
<p>Folgende Auftragsnummern der BB-Abos wurden vom n8n-Workflow angepasst:</p>

<ul style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6;">
${listenEintraege}
</ul>

<p>Mit freundlichen Grüßen<br>Jesse's n8n-Workflow</p>
`;

return [{
  json: {
    mailText,
  },
}];

